manifest=[]
def record(name,title,cap,alt,lectures,question,answer):manifest.append(dict(file=name+'.svg',title=title,caption=cap,alt=alt,lectures=lectures,question=question,answer=answer))
def diagram(name,title,cards,cap,lectures,question,answer,edges=None):
 # vertical cards with optional backward review arrow; numerals reinforce sequence.
 w=900;h=130+len(cards)*125+110
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(cap)}</desc><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="{N}"/></marker></defs><rect width="100%" height="100%" fill="white"/><g font-family="sans-serif"><text x="40" y="50" font-size="27" font-weight="bold" fill="{N}">{html.escape(title)}</text>']
 for i,(head,body) in enumerate(cards):
  y=85+i*125;col=B if i==0 else (T if i==len(cards)-1 else N)
  s.append(f'<rect x="70" y="{y}" width="730" height="95" rx="10" fill="#f3f7fb" stroke="{col}" stroke-width="2"/><text x="90" y="{y+28}" font-size="20" font-weight="bold" fill="{col}">{i+1}. {html.escape(head)}</text>')
  for j,line in enumerate(textwrap.wrap(body,85)):s.append(f'<text x="90" y="{y+55+j*22}" font-size="17" fill="{N}">{html.escape(line)}</text>')
  if i<len(cards)-1:s.append(f'<path d="M435,{y+96} L435,{y+123}" stroke="{N}" stroke-width="2" marker-end="url(#arrow)"/>')
 for j,line in enumerate(textwrap.wrap(cap,90)):s.append(f'<text x="40" y="{h-75+j*22}" font-size="16" fill="{N}">{html.escape(line)}</text>')
 s.append('</g></svg>');(O/(name+'.svg')).write_text(''.join(s));record(name,title,cap,cap,lectures,question,answer)
def chart(name,title,cap,lectures,q,a,draw,size=(10,8)):
 fig=plt.figure(figsize=size);draw(fig);fig.suptitle(title,x=.08,ha='left',color=N,fontsize=17,weight='bold');fig.subplots_adjust(top=.88,bottom=.18,hspace=.5,wspace=.3)
 fig.text(.08,.035,'\n'.join(textwrap.wrap(cap,110)),fontsize=10,color=N)
 fig.savefig(O/(name+'.svg'),bbox_inches='tight',facecolor='white');plt.close(fig);record(name,title,cap,cap,lectures,q,a)
diagram('l1-analytics-types','One question, four analytical approaches',[
 ('Descriptive: what happened?','Orders fell from 1000 to 800: a 20% decrease.'),('Diagnostic: what is associated with the change?','Compare device, region, traffic, and checkout changes; investigate alternatives.'),('Predictive: what might happen?','Estimate future orders with a validated model and uncertainty.'),('Prescriptive: what should we do?','Choose an intervention subject to budget, risk, and an evaluation plan.')], 'Illustrative retail scenario. Observational diagnostics alone do not establish causation.',[1],'Can an association prove why orders fell?','No. A causal claim requires a suitable design and assumptions.')
# Custom branching architecture and ETL comparison.
def retail_pipeline():
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1100"><title>Retail analytics pipeline</title><desc>Sources feed immutable raw storage, transformation and validation. Failed records go to review; curated facts and dimensions feed Power BI. Dashed connections denote operational support.</desc><defs><marker id="arr" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3z" fill="{N}"/></marker></defs><rect width="100%" height="100%" fill="white"/><g font-family="sans-serif"><text x="30" y="45" font-size="28" fill="{N}" font-weight="bold">Retail analytics pipeline</text>']
 def box(x,y,w,h,lines,col=N):
  s.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="#f3f7fb" stroke="{col}" stroke-width="2"/>')
  for j,line in enumerate(lines):s.append(f'<text x="{x+w/2}" y="{y+28+j*23}" text-anchor="middle" font-size="17" fill="{col}">{html.escape(line)}</text>')
 def arrow(x1,y1,x2,y2,dash=False):s.append(f'<path d="M{x1},{y1} L{x2},{y2}" fill="none" stroke="{N}" stroke-width="2"'+(' stroke-dasharray="6 5"' if dash else '')+' marker-end="url(#arr)"/>')
 for x,lines in [(30,['Sales CSV']),(270,['Customer database']),(510,['Product API'])]:box(x,80,210,55,lines,B);arrow(x+105,135,375,175)
 for y,lines in [(175,['Ingestion']),(275,['Immutable raw storage']),(375,['Transform and validate']),(555,['Curated FactSales','Date / Product / Customer / Region']),(700,['Power BI semantic model']),(840,['Interactive report'])]:box(130,y,490,75,lines,T if y>=555 else N)
 for a,b in [(250,275),(350,375),(450,555),(630,700),(775,840)]:arrow(375,a,375,b)
 s.append(f'<text x="390" y="505" font-size="18" fill="{T}">Pass</text>');box(660,405,300,85,['Fail: quarantine','Review / correct records'],RED);arrow(620,415,660,430);s.append(f'<path d="M810,405 L810,355 L620,405" stroke="{RED}" fill="none" stroke-width="2" marker-end="url(#arr)"/>')
 box(680,650,270,125,['SUPPORT THROUGHOUT','Orchestration / monitoring','Access control / lineage'],N);arrow(680,680,620,590,True);arrow(680,710,620,750,True)
 s.append(f'<text x="30" y="975" font-size="17" fill="{N}">Solid arrows: data flow / reprocessing. Dashed: support connections.</text><text x="30" y="1010" font-size="17" fill="{N}">Raw records stay unchanged; verified corrections enter a new processing version.</text><text x="30" y="1045" font-size="17" fill="{N}">FactSales grain: one order line. Supporting layers apply to every stage.</text></g></svg>');(O/'l2-retail-pipeline.svg').write_text(''.join(s));record('l2-retail-pipeline','Retail analytics pipeline','Immutable raw records support traceability; validated facts and dimensions feed the semantic model. Failed records are reviewed.','Three sources feed ingestion, immutable storage, transformation, curated tables, Power BI and a report; a quarantine branch reprocesses corrections.',[2],'Why keep the raw layer?','To preserve provenance and enable reproducible reprocessing.')
retail_pipeline()
def etl_elt():
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1050" role="img" aria-labelledby="title desc"><title id="title">ETL versus ELT</title><desc id="desc">Same source and target. ETL transforms in staging before loading; ELT loads raw data then transforms inside the warehouse.</desc><defs><marker id="arr" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3z" fill="{N}"/></marker></defs><rect width="100%" height="100%" fill="white"/><g font-family="sans-serif"><text x="35" y="45" font-size="28" font-weight="bold" fill="{N}">ETL versus ELT: where transformation happens</text>']
 def box(x,y,w,h,lines,col=N):
  s.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="9" fill="#f3f7fb" stroke="{col}" stroke-width="2"/>')
  for j,line in enumerate(lines):s.append(f'<text x="{x+w/2}" y="{y+30+j*24}" text-anchor="middle" font-size="18" fill="{col}">{html.escape(line)}</text>')
 def arrow(x1,y1,x2,y2):s.append(f'<path d="M{x1},{y1} L{x2},{y2}" stroke="{N}" fill="none" stroke-width="2" marker-end="url(#arr)"/>')
 box(250,80,500,70,['SAME SOURCE','Retail operational database'],B)
 for x,label in [(40,'ETL'),(535,'ELT')]:
  s.append(f'<text x="{x+200}" y="205" font-size="25" font-weight="bold" text-anchor="middle" fill="{N}">{label}</text>');box(x,230,400,70,['Extract'],B);arrow(500,150,x+200,230)
 box(40,365,400,95,['Transform + validate in staging','OUTSIDE the target'],A);arrow(240,300,240,365)
 s.append(f'<rect x="20" y="525" width="440" height="190" fill="#f0fdfa" stroke="{T}" stroke-dasharray="5 4"/><text x="45" y="555" font-size="17" fill="{N}">TARGET: analytics warehouse</text>');box(40,585,400,80,['Load curated data'],T);arrow(240,460,240,585)
 s.append(f'<rect x="515" y="330" width="440" height="385" fill="#f0fdfa" stroke="{T}" stroke-dasharray="5 4"/><text x="540" y="360" font-size="17" fill="{N}">TARGET: analytics warehouse</text>');box(535,390,400,80,['Load raw data'],B);arrow(735,300,735,390);box(535,550,400,95,['Transform + validate','INSIDE the target'],A);arrow(735,470,735,550)
 box(40,785,895,160,['Both require governance, validation, access control and lineage.','Both can retain raw history under a retention policy:','ETL can archive extracts; ELT can retain raw landing tables.','Choose by constraints, cost, privacy and workload.'],N)
 s.append(f'<text x="40" y="990" font-size="18" fill="{N}">Amber + location labels: transformation. Dashed boundary: target environment.</text><text x="40" y="1020" font-size="18" fill="{N}">Solid arrows: data flow. Neither approach is always superior.</text></g></svg>')
 (O/'l2-etl-elt.svg').write_text(''.join(s));record('l2-etl-elt','ETL versus ELT: transformation location','Same retail operational database and analytics warehouse in both. ETL transforms before loading; ELT loads raw then transforms inside the target. Both require governance and can retain raw history.','Two parallel data paths: ETL extraction, staging transformation outside the warehouse, and curated load; ELT extraction, raw warehouse load, and transformation within the warehouse. Amber and location labels identify transformation.',[2],'Can ETL retain raw history?','Yes. It can archive extracts before transformation; neither approach is universally superior.')
etl_elt()
