def shape(fig):
 rng=np.random.default_rng(11);samples=[rng.normal(0,1,3000),rng.lognormal(0,.65,3000),-rng.lognormal(0,.65,3000),np.r_[rng.normal(-2,.4,1500),rng.normal(2,.4,1500)]]
 for i,(x,title) in enumerate(zip(samples,['Symmetric unimodal','Right-skewed','Left-skewed','Symmetric bimodal'])):
  ax=fig.add_subplot(2,2,i+1);ax.hist(x,bins=45,color=B,alpha=.65,density=True);ax.axvline(x.mean(),color=RED,label=f'Mean {x.mean():.2f}');ax.axvline(np.median(x),color=T,ls='--',label=f'Median {np.median(x):.2f}');ax.set_title(title);ax.set_ylabel('Density');ax.legend(fontsize=8)
chart('l11-distribution-shapes','Shape is more than mean and SD','Synthetic samples, seed 11. Mean–median–mode ordering is not a universal theorem; a symmetric distribution can have two modes.',[11],'Does symmetry guarantee a unique mode?','No. The bimodal example has two peaks.',shape)
def dispersion(fig):
 ax=fig.add_subplot();x=np.array([-2,-1,0,1,2]);y=3*x
 for i,(z,label) in enumerate([(x,'Narrow'),(y,'Wide')]):ax.scatter(z,np.full(5,i),color=B if i==0 else T);ax.text(-6,.3+i,f'{label}: mean={z.mean():.0f}, SD={z.std(ddof=0):.3f}, IQR={np.percentile(z,75)-np.percentile(z,25):.0f}')
 ax.set_ylim(-.5,1.7);ax.set_yticks([0,1],['Narrow','Wide']);ax.set_xlabel('Unitless value')
chart('l11-spread','Same center, different spread','Exact samples: narrow [-2,-1,0,1,2]; wide [-6,-3,0,3,6]. Population SD; linear-interpolated quartiles.',[11],'Can equal means imply equal variability?','No.',dispersion,size=(10,5))
def correlations(fig):
 rng=np.random.default_rng(12);x=np.linspace(-2,2,100);ys=[x+rng.normal(0,.15,100),-x+rng.normal(0,.15,100),rng.normal(0,1,100),x*x,np.exp(x)]
 for i,(y,title) in enumerate(zip(ys,['Positive linear','Negative linear','No clear association','U-shaped','Monotonic nonlinear'])):
  ax=fig.add_subplot(3,2,i+1);ax.scatter(x,y,s=9,color=B);ax.set_title(f'{title}\nPearson={stats.pearsonr(x,y).statistic:.3f}; Spearman={stats.spearmanr(x,y).statistic:.3f}',fontsize=10);ax.set_xlabel('x');ax.set_ylabel('y')
chart('l12-correlations','Association depends on relationship shape','Synthetic examples, seed 12. A near-zero Pearson coefficient does not rule out a nonlinear association. Neither coefficient proves causation.',[12],'Why is the U-shape correlation weak?','Positive and negative slopes cancel in a linear summary.',correlations,size=(10,11))
diagram('l12-test-selection','Choose the question before the test',[('Independent numerical groups','Mean difference: Welch t-test for two; ANOVA/Welch ANOVA for three or more.'),('Paired numerical observations','Paired t-test on differences; Wilcoxon signed-rank needs suitable symmetry.'),('Rank / distribution comparison','Mann–Whitney U or Kruskal–Wallis; not general tests of means.'),('Categorical association','Chi-square: check expected counts; sparse 2×2 tables may use Fisher exact.'),('Numerical association','Pearson for linear; Spearman for monotonic ranks. Plot first.'),('Report and qualify','Independence, assumptions, effect size, confidence interval, p-value, multiplicity.')], 'A normality test alone does not choose the method. The design and estimand determine interpretation.',[12],'What does Mann–Whitney generally compare?','Distributions/ranks; a location interpretation needs additional assumptions.')
