def time(fig):
 rng=np.random.default_rng(14);t=np.arange(36);trend=100+.8*t;season=12*np.sin(2*np.pi*t/12);noise=rng.normal(0,3,36);y=trend+season+noise;ma=pd.Series(y).rolling(3,min_periods=3).mean()
 for i,(values,label) in enumerate([(y,'Observed and trailing 3-month mean'),(trend,'Known synthetic trend'),(season,'Known annual seasonal component'),(noise,'Generated noise')]):
  ax=fig.add_subplot(4,1,i+1);ax.plot(t+1,values,color=B);ax.set_title(label,loc='left',fontsize=10);ax.set_ylabel('Synthetic index units');ax.grid(alpha=.2)
  if i==0:ax.plot(t+1,ma,color=T,label='Trailing 3 months');ax.legend(fontsize=9)
 ax.set_xlabel('Month number')
